&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color:black&quot;&gt;HAYVANCILIKTA ŞAP FELAKETİ&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Genel Başkanımız Mahmut Arıkan, T&amp;uuml;rkiye&amp;rsquo;de tarım ve hayvancılıkta &amp;ccedil;&amp;ouml;k&amp;uuml;ş yaşandığını aktardı. Hayvancılık i&amp;ccedil;in ciddi bir tehdit haline gelen şap hastalığıyla m&amp;uuml;cadelede iktidarın sınıfta kaldığının altını &amp;ccedil;izen Arıkan, &amp;ldquo;60 yıl sonra yeniden ortaya &amp;ccedil;ıkan bu hastalık, bug&amp;uuml;n k&amp;ouml;yl&amp;uuml;m&amp;uuml;z&amp;uuml;n ahırını kırıp ge&amp;ccedil;iriyor. Devletin geciken aşı programı, &amp;ccedil;ift&amp;ccedil;iyi kaderiyle baş başa bıraktı. Halbuki zamanında &amp;ouml;nlem alınsaydı bu noktaya gelinmezdi. Ger&amp;ccedil;ekleri gizleyerek değil,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;şeffaflıkla ve bilime kulak vererek bu salgınla m&amp;uuml;cadele edilir. Ama iktidar hayvan &amp;uuml;reticisine bunu bile &amp;ccedil;ok g&amp;ouml;rd&amp;uuml;&amp;rdquo; değerlendirmesini yaptı.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&amp;nbsp;&lt;/p&gt;

